Q: Inputs dynamically added and filled out in new Mozilla version A: <pre><code>I used the mozilla debugger and gemini to find the code error, this is my working code:
&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;es&quot;&gt;
&lt;head&gt;
    &lt;meta charset=&quot;utf-8&quot;&gt;
    &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;IE=edge&quot;&gt;
    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;
    &lt;title&gt;Count Months&lt;/title&gt;
    &lt;link rel=&quot;stylesheet&quot; type=&quot;text/css&quot; href=&quot;bootstrap-3.3.6/dist/css/bootstrap.min.css&quot;&gt;
    &lt;script src=&quot;https://ajax.googleapis.com/ajax/libs/jquery/3.7.1/jquery.min.js&quot;&gt;&lt;/script&gt;
    &lt;link rel=&quot;stylesheet&quot; href=&quot;libcss/style.css&quot; type=&quot;text/css&quot; media=&quot;all&quot; /&gt;

    &lt;script language=&quot;JavaScript&quot;&gt;
    // Nota: Eliminamos la primera función FillupInputs duplicada que sobreescribía a la segunda

    function myFunction_debt(office_id){
        if(!office_id) return; // Si selecciona la opción vacía, no hace nada

        $.ajax({
            url: 'librerias/php/count_month.php',
            type: 'POST',
            dataType: 'json',
            data: { office_id: office_id },  
            success: function(data) {                   
                alert(&quot;Months: &quot; + data.quantity);

                // Pasamos los datos como parámetros al creador de inputs
                Add_Inputs(data.quantity, data.office_id, data.yearmonthd);             
            },
            error: function(xhr, status, errorThrown) {
                console.error(&quot;Error en AJAX:&quot;, errorThrown);
                alert(&quot;Error al obtener los datos de la oficina.&quot;);
            }
        });
    }

    // Modificamos para manejar el flujo asíncrono
    function Add_Inputs(quantity, office_id, yearmonthd) {
        $('#head').text('Months (Uncheck If you want):');

        // Limpiamos el contenedor por si cambia de oficina
        $(&quot;#YearMonthsInputs&quot;).empty(); 

        let cargados = 0;

        for (let i = 0; i &lt; quantity; i++) {        
            // Creamos un contenedor temporal para cada fila
            let $wrapper = $(&quot;&lt;div&gt;&lt;/div&gt;&quot;);

            $wrapper.load(&quot;DinamyInputsdebt.php&quot;, function() {
                // Añadimos el contenido al contenedor principal
                $(&quot;#YearMonthsInputs&quot;).append($wrapper.html());

                cargados++;
                // CUANDO SE HAYAN CARGADO TODOS: Ejecutamos el llenado de datos
                if (cargados === parseInt(quantity)) {
                    FillupInputs(quantity, office_id, yearmonthd);
                }
            });
        }
    }

    function FillupInputs(quantity, office_id, yearmonthd) {
        for (let i = 0; i &lt; quantity; i++) {
            // Se usa el índice i de manera segura porque el DOM ya está listo
            $('input[name=&quot;expense_select[]&quot;]').eq(i).val(yearmonthd[i]);
            $('input[name=&quot;yearmonthd[]&quot;]').eq(i).val(yearmonthd[i]);
            $('input[name=&quot;office_id[]&quot;]').eq(i).val(office_id[i]);
        }
        $(&quot;#datepicker2&quot;).removeClass(&quot;grey&quot;);
    }
    &lt;/script&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;br&gt;&lt;br&gt;
&lt;div class=&quot;signup-form&quot;&gt;
    &lt;form action=&quot;process.php&quot; method=&quot;post&quot; id=&quot;generarfactura_form&quot;&gt;
        &lt;h2&gt;Get Months&lt;/h2&gt;
        &lt;div class=&quot;form-group&quot;&gt;
            &lt;div class=&quot;row&quot;&gt;   
                &lt;div class=&quot;col-sm-4&quot;&gt;
                    &lt;label&gt;Select office:&lt;/label&gt;
                    &lt;select required id=&quot;select_ofic&quot; name=&quot;select_ofic&quot; class=&quot;form-control&quot; onchange=&quot;myFunction_debt(this.value)&quot;&gt;
                        &lt;option value=&quot;&quot;&gt;Select Ofic.&lt;/option&gt;
                        &lt;?php include(&quot;librerias/php/fetchmonth.php&quot;) ?&gt;
                    &lt;/select&gt;
                &lt;/div&gt;
            &lt;/div&gt;
        &lt;/div&gt;

        &lt;label id=&quot;head&quot;&gt;&lt;/label&gt;
        &lt;div id=&quot;YearMonthsInputs&quot;&gt;&lt;/div&gt;

        &lt;div class=&quot;form-group&quot;&gt;
            &lt;button type=&quot;submit&quot; class=&quot;btn btn-success btn-lg&quot;&gt;Process&lt;/button&gt;
        &lt;/div&gt;
    &lt;/form&gt;
&lt;/div&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

Q: Why do my property sheet outlook bar icons have a magenta tinge? A: <p>I inspected the definition for <code>SetIconsList</code> and saw an override:</p>
<pre class="lang-cpp prettyprint-override"><code>BOOL SetIconsList(UINT uiImageListResID, int cx, COLORREF clrTransparent = RGB(255, 0, 255));
</code></pre>
<p>So, all I needed to do was use:</p>
<pre class="lang-cpp prettyprint-override"><code>SetIconsList(IDB_PNG_MEETING_MATERIAL_LIGHT, 32);
</code></pre>
<p><a href="https://i.sstatic.net/MdlJPKpB.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/MdlJPKpB.png" alt="New icons" /></a></p>
<p>No magenta tinge now.</p>
<p>For reference, I did a deepo dive into the MFC sources:</p>
<pre class="lang-cpp prettyprint-override"><code>BOOL CMFCPropertySheet::SetIconsList(UINT uiImageListResID, int cx, COLORREF clrTransparent)
{
    ASSERT_VALID(this);

    ENSURE(uiImageListResID != 0);

    HBITMAP hbmp = NULL;

    // Try to load PNG image first:
    CPngImage pngImage;
    if (pngImage.Load(MAKEINTRESOURCE(uiImageListResID)))
    {
        hbmp = (HBITMAP) pngImage.Detach();
    }
    else
    {
        hbmp = (HBITMAP) ::LoadImageW(AfxFindResourceHandle(MAKEINTRESOURCE(uiImageListResID), RT_BITMAP), MAKEINTRESOURCEW(uiImageListResID), IMAGE_BITMAP, 0, 0, LR_CREATEDIBSECTION);
    }

    if (hbmp == NULL)
    {
        TRACE(_T(&quot;Can't load image: %x\n&quot;), uiImageListResID);
        return FALSE;
    }

    CImageList icons;
    m_bAlphaBlendIcons = FALSE;

    BITMAP bmpObj;
    ::GetObject(hbmp, sizeof(BITMAP), &amp;bmpObj);

    UINT nFlags = (clrTransparent == (COLORREF) -1) ? 0 : ILC_MASK;

    switch (bmpObj.bmBitsPixel)
    {
    case 4:
    default:
        nFlags |= ILC_COLOR4;
        break;

    case 8:
        nFlags |= ILC_COLOR8;
        break;

    case 16:
        nFlags |= ILC_COLOR16;
        break;

    case 24:
        nFlags |= ILC_COLOR24;
        break;

    case 32:
        nFlags |= ILC_COLOR32;
        m_bAlphaBlendIcons = TRUE;
        break;
    }

    icons.Create(cx, bmpObj.bmHeight, nFlags, 0, 0);
    icons.Add(CBitmap::FromHandle(hbmp), clrTransparent);

    SetIconsList(icons);

    ::DeleteObject(hbmp);
    return TRUE;
}
</code></pre>
<p>The <code>m_bAlphaBlendIcons </code> variable appears to be the key but I do not ee it listed in the official <a href="https://learn.microsoft.com/en-us/cpp/mfc/reference/cmfcpropertysheet-class?view=msvc-170" rel="nofollow noreferrer">documentation</a>.</p>
